insert into public.hw_programs (slug, category, name, short_desc, description, price, price_unit, price_note, options, suitable_for, includes, precautions, duration, brand, related_article_slug, tags, sort_order, is_featured, is_published) values
('flu-vaccine', 'vaccine', 'วัคซีนไข้หวัดใหญ่ 4 สายพันธุ์', 'ฉีดปีละ 1 เข็ม สำหรับผู้ใหญ่และเด็กอายุ 9 ปีขึ้นไป แพทย์ประเมินก่อนฉีดทุกครั้ง', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีนไข้หวัดใหญ่ชนิด 4 สายพันธุ์ แนะนำให้ฉีดเป็นประจำทุกปี เพราะภูมิคุ้มกันจากวัคซีนจะค่อย ๆ ลดลง และสายพันธุ์ที่ระบาดเปลี่ยนไปทุกปี"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ผู้ใหญ่และเด็กอายุ 9 ปีขึ้นไปฉีดปีละ 1 เข็ม ส่วนเด็กอายุต่ำกว่า 9 ปีที่ฉีดครั้งแรก อาจต้องฉีด 2 เข็มห่างกันอย่างน้อย 4 สัปดาห์ตามดุลยพินิจของแพทย์"}}], "version": "2.29.1"}', 390, 'ต่อเข็ม', null, '[]'::jsonb, array['ทุกคนอายุ 6 เดือนขึ้นไป','ผู้สูงอายุ 65 ปีขึ้นไป','หญิงตั้งครรภ์ (ฉีดได้ทุกไตรมาส)','ผู้มีโรคประจำตัว เช่น เบาหวาน โรคหัวใจ โรคปอด']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['หากมีไข้หรือป่วยเฉียบพลัน แพทย์อาจแนะนำให้เลื่อนฉีด','แจ้งแพทย์หากเคยแพ้วัคซีนหรือส่วนประกอบของวัคซีน']::text[], null, null, 'flu-vaccine-2569', array['วัคซีน','ไข้หวัดใหญ่']::text[], 1, true, true),
('dengue-vaccine-qdenga', 'vaccine', 'วัคซีนไข้เลือดออก (Qdenga)', 'ฉีด 2 เข็ม ห่างกัน 3 เดือน สำหรับผู้มีอายุ 4 ปีขึ้นไป แบ่งจ่ายรายเข็มได้', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีน Qdenga (TAK-003) เป็นวัคซีนป้องกันโรคไข้เลือดออกที่ใช้กันแพร่หลายในไทย ขึ้นทะเบียนใช้ในผู้ที่มีอายุตั้งแต่ 4 ปีขึ้นไป"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ฉีดทั้งหมด 2 เข็ม ห่างกัน 3 เดือน หากเข็มที่สองล่าช้ากว่ากำหนดไม่จำเป็นต้องเริ่มนับหนึ่งใหม่ ฉีดต่อได้เลยเมื่อมีโอกาส"}}], "version": "2.29.1"}', 1800, 'ต่อเข็ม', 'จองคอร์ส 2 เข็ม 3,450 บาท', '[{"label": "วัคซีน 1 เข็ม (แบ่งจ่ายรายเข็ม)", "price": 1800, "note": "ฉีดทั้งหมด 2 เข็ม ห่างกัน 3 เดือน"}, {"label": "คอร์ส 2 เข็ม", "price": 3450, "note": "ชำระครั้งเดียวครบทั้งคอร์ส"}]'::jsonb, array['ผู้มีอายุ 4 ปีขึ้นไป','ผู้ที่อาศัยหรือทำงานในพื้นที่ที่มีการระบาด','ผู้ที่เคยเป็นไข้เลือดออกมาก่อน (ตามคำแนะนำแพทย์)']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['ผู้ที่ตั้งครรภ์ ให้นมบุตร หรือมีภูมิคุ้มกันบกพร่อง ควรปรึกษาแพทย์ก่อนฉีด','หากมีไข้สูงเฉียบพลันช่วงที่มีการระบาด ควรพบแพทย์ ไม่ควรซื้อยาแก้ปวดกลุ่ม NSAIDs กินเอง']::text[], '2 เข็ม ห่างกัน 3 เดือน', 'Qdenga (TAK-003) — Takeda', 'dengue-vaccine-2569', array['วัคซีน','ไข้เลือดออก']::text[], 2, true, true),
('pneumococcal-vaccine-prevnar-20', 'vaccine', 'วัคซีนปอดอักเสบ (Prevnar 20)', 'ผู้ใหญ่ที่ไม่เคยฉีดวัคซีนไอพีดีมาก่อน ฉีดเพียง 1 เข็ม', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีน Prevnar 20 ป้องกันการติดเชื้อนิวโมคอคคัส (ไอพีดี) ซึ่งเป็นสาเหตุสำคัญของปอดอักเสบ ติดเชื้อในกระแสเลือด และเยื่อหุ้มสมองอักเสบ"}}, {"id": "b1", "type": "paragraph", "data": {"text": "สำหรับผู้ใหญ่ทั่วไปที่ไม่เคยฉีดวัคซีนไอพีดีมาก่อน ฉีด Prevnar 20 เพียง 1 เข็ม"}}], "version": "2.29.1"}', 3000, 'ต่อเข็ม', null, '[]'::jsonb, array['ผู้สูงอายุ 65 ปีขึ้นไป','ผู้มีโรคเรื้อรังหรือภูมิคุ้มกันบกพร่อง ไม่ว่าอายุเท่าไหร่','ผู้ใหญ่ทั่วไปที่ต้องการป้องกัน']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['แจ้งแพทย์หากเคยฉีดวัคซีนไอพีดีชนิดอื่นมาก่อน เพื่อวางแผนการฉีดให้เหมาะสม']::text[], '1 เข็ม', 'Prevnar 20 (PCV20)', 'pneumonia-vaccine-2569', array['วัคซีน','ปอดอักเสบ','ผู้สูงอายุ']::text[], 3, false, true),
('rsv-vaccine-abrysvo', 'vaccine', 'วัคซีน RSV (Abrysvo)', 'ฉีด 1 เข็ม สำหรับผู้ใหญ่อายุ 60 ปีขึ้นไป และหญิงตั้งครรภ์อายุครรภ์ 24–36 สัปดาห์', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "RSV เป็นไวรัสทางเดินหายใจที่อาจทำให้เกิดอาการรุนแรงในผู้สูงอายุ ผู้มีโรคเรื้อรัง และทารก วัคซีน Abrysvo ครอบคลุมไวรัส RSV ทั้งสายพันธุ์ย่อย A และ B"}}, {"id": "b1", "type": "paragraph", "data": {"text": "วัคซีน RSV ฉีดเพียง 1 เข็ม ไม่ต้องฉีดซ้ำทุกปีเหมือนวัคซีนไข้หวัดใหญ่"}}], "version": "2.29.1"}', 7200, 'ต่อเข็ม', null, '[]'::jsonb, array['ผู้ใหญ่อายุ 60 ปีขึ้นไป','ผู้ใหญ่อายุ 50–59 ปีที่มีโรคปอด โรคหัวใจ หรือโรคเรื้อรัง','หญิงตั้งครรภ์อายุครรภ์ 24–36 สัปดาห์ เพื่อป้องกันทารกแรกเกิด']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['หญิงตั้งครรภ์ควรฉีดตามช่วงอายุครรภ์ที่แพทย์แนะนำ']::text[], '1 เข็ม', 'Abrysvo', 'rsv-vaccine-2569', array['วัคซีน','RSV','ผู้สูงอายุ']::text[], 4, false, true),
('hepatitis-b-vaccine', 'vaccine', 'วัคซีนไวรัสตับอักเสบบี', 'ฉีดครบ 3 เข็ม จ่ายครบคอร์สเข็มละ 500 บาท หรือจ่ายทีละเข็ม เข็มละ 600 บาท', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีนป้องกันไวรัสตับอักเสบบี ฉีดตามตารางมาตรฐาน 3 เข็ม ที่ 0, 1 และ 6 เดือน"}}, {"id": "b1", "type": "paragraph", "data": {"text": "เลือกจ่ายครบคอร์สล่วงหน้าเข็มละ 500 บาท หรือจ่ายทีละเข็มเข็มละ 600 บาท หากฉีดไม่ครบตามนัด ไม่ต้องเริ่มนับหนึ่งใหม่"}}], "version": "2.29.1"}', 500, 'เริ่มต้นต่อเข็ม', null, '[{"label": "จ่ายครบคอร์ส 3 เข็ม", "price": 1500, "note": "เฉลี่ยเข็มละ 500 บาท"}, {"label": "จ่ายทีละเข็ม", "price": 600, "note": "ต่อเข็ม"}]'::jsonb, array['ผู้ที่ยังไม่มีภูมิคุ้มกันต่อไวรัสตับอักเสบบี']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีน','นัดหมายเข็มถัดไป']::text[], array['ผู้ที่ตั้งครรภ์ควรปรึกษาแพทย์ก่อนฉีด']::text[], '3 เข็ม (เดือนที่ 0, 1, 6)', null, null, array['วัคซีน','ตับอักเสบบี']::text[], 5, false, true),
('hpv-vaccine-gardasil-9', 'vaccine', 'วัคซีน HPV (Gardasil 9)', 'วัคซีนป้องกันเชื้อไวรัส HPV 9 สายพันธุ์ จำนวนเข็มขึ้นกับอายุ แพทย์จะแนะนำตารางฉีดที่เหมาะสม', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีน Gardasil 9 ป้องกันการติดเชื้อไวรัส HPV 9 สายพันธุ์ ซึ่งเกี่ยวข้องกับมะเร็งปากมดลูกและโรคอื่น ๆ ที่เกิดจากเชื้อ HPV"}}, {"id": "b1", "type": "paragraph", "data": {"text": "จำนวนเข็มและระยะห่างขึ้นกับอายุที่เริ่มฉีด แพทย์จะประเมินและแนะนำตารางฉีดที่เหมาะสมกับแต่ละคน"}}], "version": "2.29.1"}', 5500, 'ต่อเข็ม', null, '[]'::jsonb, array['ผู้หญิงและผู้ชายตามช่วงอายุที่แพทย์แนะนำ']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['ผู้ที่ตั้งครรภ์ควรปรึกษาแพทย์ก่อนฉีด']::text[], null, 'Gardasil 9', null, array['วัคซีน','HPV']::text[], 6, false, true),
('rabies-vaccine', 'vaccine', 'วัคซีนพิษสุนัขบ้า', 'โดนหมา/แมวกัดหรือข่วน แพทย์ประเมินแผลและฉีดวัคซีนตามตารางมาตรฐาน', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "หลังโดนสัตว์กัดหรือข่วน ให้ล้างแผลด้วยน้ำสะอาดและสบู่ทันทีอย่างน้อย 15 นาที แล้วรีบพบแพทย์เพื่อประเมินความเสี่ยงของแผล"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ผู้ที่ไม่เคยฉีดวัคซีนมาก่อน แพทย์จะฉีดตามตารางมาตรฐานวันที่ 0, 3, 7 และ 14 (บางกรณีอาจนัดเพิ่มวันที่ 28) ส่วนผู้ที่เคยฉีดป้องกันไว้แล้วมักฉีดกระตุ้นเพียง 2 เข็ม ต้องฉีดให้ครบตามนัด"}}], "version": "2.29.1"}', 390, 'ต่อเข็ม', 'ค่าทำแผล/ล้างแผล 50 บาท และค่าเย็บแผล (กรณีจำเป็น) 50 บาทต่อเข็ม คิดแยก', '[{"label": "วัคซีนพิษสุนัขบ้า", "price": 390, "note": "ต่อเข็ม"}, {"label": "ทำแผล / ล้างแผล", "price": 50, "note": "ต่อครั้ง"}, {"label": "เย็บแผล (กรณีจำเป็น)", "price": 50, "note": "ต่อเข็ม"}]'::jsonb, array['ผู้ที่โดนหมา แมว หรือสัตว์เลี้ยงลูกด้วยนมกัด ข่วน หรือเลียแผล']::text[], array['ประเมินแผลโดยแพทย์','ค่าวัคซีนและค่าฉีด','นัดหมายเข็มถัดไป']::text[], array['ห้ามหยุดฉีดกลางคันแม้แผลจะหายดีแล้ว','หญิงตั้งครรภ์ฉีดได้ เพราะโรคนี้อันตรายถึงชีวิต']::text[], '4 เข็ม (วันที่ 0, 3, 7, 14) หรือตามแพทย์นัด', null, 'rabies-vaccine-2569', array['วัคซีน','พิษสุนัขบ้า','สัตว์กัด']::text[], 7, false, true),
('health-checkup-basic', 'checkup', 'แพ็กเกจตรวจสุขภาพ ชุดเล็ก', 'ตรวจครบ 16 รายการ น้ำตาล ไขมัน ตับ ไต ไวรัสตับบี ในราคา 999 บาท พร้อมแพทย์อ่านผล', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "เจาะเลือดครั้งเดียว ได้รู้ค่าสุขภาพสำคัญ 16 รายการ ทั้งน้ำตาล ไขมัน ตับ ไต และไวรัสตับอักเสบบี แพทย์อธิบายผลให้เข้าใจง่ายว่าค่าไหนปกติ ค่าไหนต้องดูแล"}}], "version": "2.29.1"}', 999, 'ต่อชุด', null, '[]'::jsonb, array['คนวัยทำงานที่อยากเช็คสุขภาพพื้นฐานปีละครั้ง','ผู้ที่ไม่เคยตรวจสุขภาพมาก่อน','ผู้ที่อยากรู้ค่าน้ำตาล ไขมัน ตับ ไต ของตัวเอง']::text[], array['น้ำตาลในเลือด (FBS) — คัดกรองเบาหวาน','ไขมันในเลือด 4 ค่า — คอเลสเตอรอล, ไตรกลีเซอไรด์, ไขมันดี (HDL), ไขมันไม่ดี (LDL)','การทำงานของไต 3 ค่า — BUN, Creatinine, อัตราการกรองของไต (eGFR)','กรดยูริก — ดูความเสี่ยงโรคเกาต์','การทำงานของตับ (Liver Function Test)','ความสมบูรณ์ของเม็ดเลือด (CBC) — ดูภาวะโลหิตจางและการติดเชื้อ','ไวรัสตับอักเสบบี 2 ค่า — ตรวจเชื้อ (HBsAg) และภูมิคุ้มกัน (HBsAb)','ซิฟิลิส (VDRL)','ตรวจปัสสาวะ (UA)','วัดน้ำหนัก ส่วนสูง ดัชนีมวลกาย (BMI)','แพทย์อ่านผลและให้คำแนะนำ']::text[], array['ควรงดอาหาร 8–10 ชั่วโมงก่อนเจาะเลือด ดื่มน้ำเปล่าได้ (แนะนำมาช่วงเช้า)']::text[], null, null, null, array['ตรวจสุขภาพ']::text[], 8, true, true),
('health-checkup-female', 'checkup', 'แพ็กเกจตรวจสุขภาพ ชุดใหญ่ (ผู้หญิง)', 'ชุดใหญ่ 23 รายการ ตรวจตับละเอียด เพิ่มหมู่เลือด แคลเซียม และสารบ่งชี้มะเร็งตับ-ทางเดินอาหาร', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ละเอียดกว่าชุดเล็ก ตรวจตับ 3 ค่า รู้หมู่เลือด ระดับแคลเซียม และค่าสารบ่งชี้มะเร็งตับและทางเดินอาหาร เจาะเลือดครั้งเดียว แพทย์อธิบายผลทุกค่าให้เข้าใจง่าย"}}], "version": "2.29.1"}', 1300, 'ต่อชุด', null, '[]'::jsonb, array['ผู้หญิงที่อยากตรวจละเอียดกว่าชุดเล็ก','ผู้ที่มีประวัติครอบครัวเป็นโรคตับ เบาหวาน หรือไขมันสูง','ผู้ที่ยังไม่รู้หมู่เลือดของตัวเอง']::text[], array['น้ำตาลในเลือด (FBS) — คัดกรองเบาหวาน','ไขมันในเลือด 4 ค่า — คอเลสเตอรอล, ไตรกลีเซอไรด์, ไขมันดี (HDL), ไขมันไม่ดี (LDL)','การทำงานของไต 3 ค่า — BUN, Creatinine, อัตราการกรองของไต (eGFR)','กรดยูริก — ดูความเสี่ยงโรคเกาต์','การทำงานของตับ 3 ค่า — SGOT, SGPT, ALP','ความสมบูรณ์ของเม็ดเลือด (CBC) — ดูภาวะโลหิตจางและการติดเชื้อ','ไวรัสตับอักเสบบี 2 ค่า — ตรวจเชื้อ (HBsAg) และภูมิคุ้มกัน (HBsAb)','ซิฟิลิส (VDRL)','ตรวจปัสสาวะ (UA)','หมู่เลือด ABO และ Rh','แคลเซียมในเลือด (Calcium)','สารบ่งชี้มะเร็งตับ (AFP)','สารบ่งชี้มะเร็งทางเดินอาหาร (CEA)','วัดน้ำหนัก ส่วนสูง ดัชนีมวลกาย (BMI)','แพทย์อ่านผลและให้คำแนะนำ']::text[], array['ควรงดอาหาร 8–10 ชั่วโมงก่อนเจาะเลือด ดื่มน้ำเปล่าได้ (แนะนำมาช่วงเช้า)','สารบ่งชี้มะเร็ง (AFP, CEA) ใช้ประกอบการคัดกรองเท่านั้น ไม่ใช่การวินิจฉัยมะเร็ง แพทย์จะแปลผลร่วมกับอาการและประวัติ']::text[], null, null, null, array['ตรวจสุขภาพ']::text[], 9, false, true),
