('contraceptive-injection-3-month', 'family-planning', 'ฉีดยาคุมกำเนิด 3 เดือน (DMPA)', 'ฉีดครั้งเดียวคุมกำเนิดได้นาน 3 เดือน แพทย์ให้คำปรึกษาก่อนฉีดทุกครั้ง', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ยาฉีดคุมกำเนิด DMPA แบบ 3 เดือน ฉีดครั้งเดียวคุมกำเนิดได้นาน 3 เดือน เหมาะกับคนที่ไม่สะดวกกินยาคุมทุกวัน"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ข้อควรรู้คือประจำเดือนอาจมาไม่ปกติหรือหายไปช่วงที่ใช้ และหลังหยุดฉีดอาจต้องรอสักระยะกว่าจะกลับมามีบุตรได้ตามปกติ"}}], "version": "2.29.1"}', 100, 'ต่อเข็ม', null, '[]'::jsonb, array['คนที่ไม่สะดวกกินยาคุมทุกวัน','คนที่มีผลข้างเคียงจากยาคุมชนิดฮอร์โมนรวม']::text[], array['คำปรึกษาจากแพทย์ก่อนฉีด','ค่ายาและค่าฉีด']::text[], array['ยาฉีดคุมกำเนิดไม่ป้องกันโรคติดต่อทางเพศสัมพันธ์']::text[], 'คุมกำเนิดได้ 3 เดือน', null, 'contraception-injection-2569', array['คุมกำเนิด']::text[], 12, false, true),
('contraceptive-injection-monthly', 'family-planning', 'ฉีดยาคุมกำเนิดรายเดือน', 'ยาฉีดฮอร์โมนรวม ฉีดทุกเดือน รอบเดือนมาสม่ำเสมอกว่ายาฉีด 3 เดือน', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ยาฉีดคุมกำเนิดรายเดือนเป็นทางเลือกสำหรับคนที่เคยใช้ยาฉีด 3 เดือนแล้วมีปัญหาประจำเดือนมาไม่ปกติ"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ต้องมาฉีดที่คลินิกทุกเดือน หากไม่สะดวกมาบ่อย ยาฉีด 3 เดือนอาจเหมาะกว่า ปรึกษาแพทย์เพื่อเลือกวิธีที่เหมาะกับตัวเอง"}}], "version": "2.29.1"}', 250, 'ต่อเข็ม', null, '[]'::jsonb, array['คนที่ใช้ยาฉีด 3 เดือนแล้วประจำเดือนมาไม่ปกติ','คนที่ต้องการรอบเดือนสม่ำเสมอ','คนที่สะดวกมาคลินิกทุกเดือน']::text[], array['คำปรึกษาจากแพทย์ก่อนฉีด','ค่ายาและค่าฉีด']::text[], array['ยาฉีดคุมกำเนิดไม่ป้องกันโรคติดต่อทางเพศสัมพันธ์']::text[], 'ฉีดทุกเดือน', null, 'monthly-contraceptive-injection-2569', array['คุมกำเนิด']::text[], 13, false, true),
('nebulizer', 'procedure', 'พ่นยาขยายหลอดลม (Nebulizer)', 'บรรเทาอาการหอบเหนื่อยจากหอบหืดหรือภูมิแพ้ทางเดินหายใจ', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "การพ่นยาด้วยเครื่องเนบูไลเซอร์เปลี่ยนยาน้ำให้เป็นละอองฝอยละเอียด เพื่อให้ยาเข้าสู่ทางเดินหายใจโดยตรง ช่วยขยายหลอดลมและบรรเทาอาการหอบเหนื่อย เหมาะกับเด็กเล็กหรือผู้ที่ไม่สะดวกใช้ยาพ่นชนิดสูดเอง"}}], "version": "2.29.1"}', 200, 'ต่อครั้ง', 'ค่าหน้ากากพ่นยา 200 บาท ซื้อครั้งแรกครั้งเดียว ใช้ซ้ำได้ทุกครั้งถัดไป', '[{"label": "พ่นยา", "price": 200, "note": "ต่อครั้ง"}, {"label": "พ่นยา + หน้ากากพ่นยา (ครั้งแรก)", "price": 400, "note": "หน้ากากใช้ซ้ำได้ทุกครั้งถัดไป"}]'::jsonb, '{}'::text[], array['ประเมินอาการโดยแพทย์','ค่ายาพ่น']::text[], array['หากหายใจลำบากมาก ริมฝีปากเขียว หรือพูดไม่เป็นประโยค ให้ไปโรงพยาบาลทันทีหรือโทร 1669']::text[], null, null, 'asthma-respiratory-allergy-2569', array['หอบหืด','ภูมิแพ้']::text[], 14, false, true),
('wound-care', 'procedure', 'ทำแผล / เย็บแผล', 'ล้างแผล ทำแผลสด แผลผ่าตัด และเย็บแผลโดยแพทย์', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ทำแผลสด แผลผ่าตัด และเย็บแผลโดยแพทย์ พร้อมติดตามอาการจนแผลหาย กรณีแผลเกินขีดความสามารถของคลินิก แพทย์จะส่งต่อโรงพยาบาล"}}], "version": "2.29.1"}', 50, 'เริ่มต้น', null, '[{"label": "ทำแผล / ล้างแผล", "price": 50, "note": "ต่อครั้ง"}, {"label": "เย็บแผล", "price": 50, "note": "ต่อเข็ม"}]'::jsonb, '{}'::text[], array['ประเมินแผลโดยแพทย์']::text[], array['แผลลึก เลือดออกไม่หยุด หรือมีสิ่งแปลกปลอมในแผล ควรไปโรงพยาบาล']::text[], null, null, null, array['ทำแผล']::text[], 15, false, true),
('medical-certificate', 'certificate', 'ใบรับรองแพทย์', 'ใบรับรองแพทย์ 5 โรค สมัครงาน ใบขับขี่ และเอกสารราชการ เริ่มต้น 200 บาท', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ออกใบรับรองแพทย์ 5 โรค ใบรับรองแพทย์สำหรับสมัครงาน ทำใบขับขี่ และเอกสารที่ต้องใช้ใบรับรองแพทย์ ทุกประเภทเริ่มต้น 200 บาท"}}, {"id": "b1", "type": "paragraph", "data": {"text": "กรณีต้องตรวจสารเสพติดร่วมด้วย ราคา 300 บาท"}}], "version": "2.29.1"}', 200, 'เริ่มต้นต่อฉบับ', null, '[{"label": "ใบรับรองแพทย์ (5 โรค / สมัครงาน / ใบขับขี่ / ทั่วไป)", "price": 200, "note": "ต่อฉบับ"}, {"label": "ใบรับรองแพทย์ + ตรวจสารเสพติด", "price": 300, "note": "ต่อฉบับ"}]'::jsonb, '{}'::text[], array['ตรวจร่างกายโดยแพทย์','ใบรับรองแพทย์']::text[], array['นำบัตรประชาชนมาด้วย']::text[], null, null, null, array['ใบรับรองแพทย์']::text[], 16, false, true),
('pep-prep', 'sexual-health', 'PEP / PrEP ยาป้องกันเอชไอวี', 'ให้คำปรึกษาเป็นความลับ ต้องนัดหมายทาง LINE ก่อนเข้ารับบริการ', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "บริการ PEP (ยาต้านไวรัสหลังสัมผัสเชื้อ) และ PrEP (ยาป้องกันก่อนสัมผัสเชื้อ) พร้อมคำปรึกษาเป็นความลับ กรุณาทัก LINE เพื่อนัดหมายก่อนเข้ารับบริการทุกครั้ง"}}], "version": "2.29.1"}', null, null, 'สอบถามค่ายาทาง LINE @p49clinic', '[]'::jsonb, '{}'::text[], array['คำปรึกษาจากแพทย์เป็นความลับ']::text[], array['PEP ควรเริ่มยาโดยเร็วที่สุดหลังสัมผัสเชื้อ']::text[], null, null, 'pep-prep-2569', array['สุขภาพทางเพศ','HIV']::text[], 17, false, true),
('employee-health-checkup', 'checkup', 'ตรวจสุขภาพพนักงาน / บริษัท', 'แพ็กเกจตรวจสุขภาพประจำปีสำหรับบริษัทและโรงงาน ปรับรายการตรวจตามความต้องการ ขอใบเสนอราคาทาง LINE', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "บริการตรวจสุขภาพประจำปีสำหรับพนักงานบริษัทและโรงงานในเขตทุ่งครุและพื้นที่ใกล้เคียง เลือกรายการตรวจให้เหมาะกับลักษณะงานและงบประมาณของบริษัท"}}, {"id": "b1", "type": "paragraph", "data": {"text": "แพ็กเกจรายบุคคลเริ่มต้น 999 บาท สำหรับการตรวจเป็นกลุ่ม ทักแจ้งจำนวนพนักงานและรายการที่ต้องการทาง LINE เพื่อรับใบเสนอราคา"}}], "version": "2.29.1"}', null, null, 'ราคาต่อคนขึ้นกับจำนวนพนักงานและรายการตรวจ ขอใบเสนอราคาได้ทาง LINE @p49clinic', '[]'::jsonb, array['ฝ่ายบุคคล / HR ที่ต้องจัดตรวจสุขภาพประจำปีให้พนักงาน','บริษัทและโรงงานในเขตทุ่งครุและพื้นที่ใกล้เคียง','การตรวจสุขภาพก่อนเข้าทำงาน']::text[], array['ปรับรายการตรวจตามความต้องการของบริษัท','แพทย์อ่านผลและให้คำแนะนำ']::text[], '{}'::text[], null, null, null, array['ตรวจสุขภาพ','บริษัท','พนักงาน']::text[], 12, true, true),
('std-screening', 'sexual-health', 'ตรวจคัดกรองโรคติดต่อทางเพศสัมพันธ์', 'ตรวจคัดกรองและให้คำปรึกษาเป็นความลับ สอบถามรายการตรวจและราคาทาง LINE', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ตรวจคัดกรองโรคติดต่อทางเพศสัมพันธ์ พร้อมให้คำปรึกษาเป็นความลับโดยแพทย์ หากพบความผิดปกติ แพทย์จะแนะนำการรักษาหรือส่งต่อตามความเหมาะสม"}}, {"id": "b1", "type": "paragraph", "data": {"text": "คลินิกแจกถุงยางอนามัยฟรีทุกขนาด"}}], "version": "2.29.1"}', null, null, 'สอบถามรายการตรวจและราคาได้ทาง LINE @p49clinic', '[]'::jsonb, '{}'::text[], array['คำปรึกษาจากแพทย์เป็นความลับ']::text[], array['บางการตรวจต้องเว้นระยะหลังความเสี่ยงก่อนจึงจะตรวจพบ แพทย์จะแนะนำช่วงเวลาที่เหมาะสม']::text[], null, null, 'pep-prep-2569', array['สุขภาพทางเพศ']::text[], 20, false, true),
('ncd-care', 'chronic-care', 'ดูแลโรคเรื้อรัง ความดัน เบาหวาน ไขมัน', 'ตรวจติดตาม ปรับยา และให้คำแนะนำต่อเนื่องโดยแพทย์ ใกล้บ้าน ไม่ต้องไปโรงพยาบาลใหญ่', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "ดูแลผู้ป่วยความดันโลหิตสูง เบาหวาน และไขมันในเลือดสูงอย่างต่อเนื่อง ตรวจติดตามอาการ ตรวจแล็บตามนัด และปรับยาโดยแพทย์"}}, {"id": "b1", "type": "paragraph", "data": {"text": "เหมาะกับผู้ที่ต้องการรับยาและติดตามผลใกล้บ้าน ไม่ต้องเดินทางไกลหรือรอคิวนานที่โรงพยาบาลใหญ่"}}], "version": "2.29.1"}', null, null, 'ผู้มีสิทธิบัตรทองใช้สิทธิได้ตามเงื่อนไขของสิทธิ ผู้ชำระเงินสดสอบถามค่าตรวจและค่ายาได้ทาง LINE', '[]'::jsonb, array['ผู้ป่วยความดันโลหิตสูง เบาหวาน หรือไขมันในเลือดสูง','ผู้ที่ต้องการย้ายมารับยาใกล้บ้าน (นำประวัติการรักษาและยาเดิมมาด้วย)']::text[], array['ตรวจติดตามอาการโดยแพทย์','คำแนะนำการดูแลตัวเอง']::text[], array['นำยาที่ใช้อยู่และผลตรวจเดิมมาด้วยในครั้งแรก','บางการตรวจเลือดต้องงดน้ำและอาหารก่อนตรวจ']::text[], null, null, 'diabetes-hypertension-2569', array['โรคเรื้อรัง','ความดัน','เบาหวาน']::text[], 21, false, false),
('home-visit-elderly', 'chronic-care', 'ดูแลผู้สูงอายุที่บ้าน (เยี่ยมบ้าน)', 'ทีมงานคลินิกไปดูแลผู้สูงอายุถึงบ้าน สอบถามพื้นที่ให้บริการและราคาทาง LINE', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "บริการดูแลผู้สูงอายุที่บ้าน สำหรับผู้ที่เดินทางมาคลินิกไม่สะดวก ทีมงานจะประเมินและวางแผนการดูแลร่วมกับครอบครัว"}}], "version": "2.29.1"}', null, null, 'สอบถามพื้นที่ให้บริการและค่าบริการได้ทาง LINE @p49clinic', '[]'::jsonb, array['ผู้สูงอายุที่เดินทางมาคลินิกไม่สะดวก','ผู้ป่วยติดเตียงหรือพักฟื้นที่บ้าน']::text[], array['ประเมินอาการที่บ้าน','คำแนะนำการดูแลสำหรับครอบครัว']::text[], array['กรณีฉุกเฉิน โทร 1669']::text[], null, null, null, array['ผู้สูงอายุ','เยี่ยมบ้าน']::text[], 22, false, false),
('prp-knee', 'chronic-care', 'PRP ข้อเข่า (นัดปรึกษาแพทย์)', 'ทางเลือกการดูแลข้อเข่าเสื่อม ต้องนัดปรึกษาและประเมินโดยแพทย์ก่อน', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "PRP (Platelet-Rich Plasma) คือการนำเลือดของผู้รับบริการเองมาปั่นแยกเอาส่วนที่มีเกล็ดเลือดเข้มข้น แล้วฉีดเข้าข้อเข่า เป็นทางเลือกหนึ่งในการดูแลข้อเข่าเสื่อม"}}, {"id": "b1", "type": "paragraph", "data": {"text": "ความเหมาะสมและจำนวนครั้งขึ้นกับการประเมินของแพทย์ กรุณานัดปรึกษาก่อนทาง LINE"}}], "version": "2.29.1"}', null, null, 'ยังไม่มีราคาตายตัว นัดปรึกษาแพทย์เพื่อประเมินก่อน', '[]'::jsonb, array['ผู้มีอาการปวดเข่าจากข้อเข่าเสื่อม (ตามการประเมินของแพทย์)']::text[], array['ปรึกษาและประเมินโดยแพทย์ก่อนทำ']::text[], array['ผลลัพธ์แตกต่างกันในแต่ละบุคคล','แจ้งแพทย์หากใช้ยาละลายลิ่มเลือดหรือมีโรคประจำตัว']::text[], null, null, 'prp-knee-2569', array['ข้อเข่า','ผู้สูงอายุ']::text[], 23, false, false),
('tetanus-vaccine', 'vaccine', 'วัคซีนบาดทะยัก', 'ฉีดป้องกันบาดทะยัก เช่น หลังมีบาดแผล หรือฉีดกระตุ้นตามกำหนด แพทย์ประเมินก่อนฉีดทุกครั้ง', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "วัคซีนป้องกันบาดทะยัก ใช้ฉีดกระตุ้นภูมิคุ้มกันตามกำหนด หรือหลังมีบาดแผลที่เสี่ยงต่อการติดเชื้อบาดทะยัก เช่น แผลสกปรก แผลถูกของมีคมหรือตะปูตำ"}}, {"id": "b1", "type": "paragraph", "data": {"text": "จำนวนเข็มขึ้นกับประวัติการฉีดวัคซีนเดิม แพทย์จะซักประวัติและแนะนำว่าต้องฉีดกี่เข็ม"}}], "version": "2.29.1"}', 100, 'ต่อเข็ม', null, '[]'::jsonb, array['ผู้ที่มีบาดแผลและไม่แน่ใจว่าเคยฉีดวัคซีนบาดทะยักครบหรือไม่','ผู้ใหญ่ที่ถึงกำหนดฉีดกระตุ้น']::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], array['แจ้งแพทย์หากเคยแพ้วัคซีน','แผลลึกหรือสกปรกมาก ควรให้แพทย์ประเมินแผลร่วมด้วย']::text[], null, null, null, array['วัคซีน','บาดทะยัก']::text[], 8, false, true),
('child-vaccines', 'vaccine', 'วัคซีนเด็กตามวัย', 'วัคซีนเสริมสำหรับเด็กตามช่วงอายุ แพทย์ช่วยวางแผนตารางฉีด', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "[รอยืนยันชนิดวัคซีนเด็กที่คลินิกมีและราคา]"}}], "version": "2.29.1"}', null, null, null, '[]'::jsonb, '{}'::text[], array['ซักประวัติและประเมินความเหมาะสมโดยแพทย์ก่อนฉีด','ค่าวัคซีนและค่าฉีด','สังเกตอาการหลังฉีดที่คลินิก']::text[], '{}'::text[], null, null, 'child-vaccine-schedule-2569', array['วัคซีน','เด็ก']::text[], 9, false, false),
('ekg', 'checkup', 'ตรวจคลื่นไฟฟ้าหัวใจ (EKG)', 'ตรวจการทำงานของหัวใจ ใช้เวลาไม่นาน ไม่เจ็บ เหมาะกับการตรวจสุขภาพและผู้มีอาการใจสั่น เจ็บหน้าอก', '{"time": 1792584741247, "blocks": [{"id": "b0", "type": "paragraph", "data": {"text": "การตรวจคลื่นไฟฟ้าหัวใจ (EKG หรือ ECG) คือการวัดสัญญาณไฟฟ้าของหัวใจผ่านแผ่นติดที่หน้าอก แขน และขา ใช้เวลาไม่นานและไม่เจ็บ ช่วยดูจังหวะการเต้นของหัวใจและความผิดปกติบางอย่าง"}}, {"id": "b1", "type": "paragraph", "data": {"text": "นิยมตรวจร่วมกับการตรวจสุขภาพประจำปี หรือเมื่อมีอาการที่แพทย์สงสัยว่าเกี่ยวกับหัวใจ"}}], "version": "2.29.1"}', 200, 'ต่อครั้ง', null, '[]'::jsonb, array['ผู้ที่ตรวจสุขภาพประจำปี โดยเฉพาะอายุ 40 ปีขึ้นไป','ผู้มีโรคความดันโลหิตสูง เบาหวาน หรือไขมันในเลือดสูง','ผู้ที่ต้องใช้ผลตรวจหัวใจประกอบการสมัครงานหรือเอกสาร']::text[], array['ตรวจคลื่นไฟฟ้าหัวใจที่คลินิก']::text[], array['หากเจ็บแน่นหน้าอกรุนแรง หายใจไม่ออก หรือเหงื่อแตก ให้โทร 1669 หรือไปโรงพยาบาลทันที','สวมเสื้อที่ถอดหรือเปิดหน้าอกได้สะดวก']::text[], null, null, null, array['ตรวจสุขภาพ','หัวใจ']::text[], 11, false, true)
